CREATE TRIGGER IF NOT EXISTS ik_d1_erasure_progress_binding BEFORE UPDATE ON ik_d1_erasure_progress WHEN NEW.id IS NOT OLD.id OR NEW.destination IS NOT OLD.destination OR NEW.request_hash IS NOT OLD.request_hash OR NEW.created_at IS NOT OLD.created_at OR OLD.phase='complete' BEGIN SELECT RAISE(ABORT,'IMPORT_ERASURE_OPERATION_CHANGED'); END;
CREATE TRIGGER IF NOT EXISTS ik_d1_erasure_progress_delete BEFORE DELETE ON ik_d1_erasure_progress WHEN OLD.phase='complete' BEGIN SELECT RAISE(ABORT,'IMPORT_ERASURE_OPERATION_CHANGED'); END;

-- ADMIN-006: each audit entry keeps the role its actor held when it was written,
-- so the authority it names does not change when the person's role changes later.
ALTER TABLE gk_audit ADD COLUMN role TEXT;

-- PLAN-007: a duplicate work order merged into another is cancelled and keeps a
-- link to the work order that carries on; its own evidence and records stay.
ALTER TABLE gk_work_orders ADD COLUMN merged_into TEXT REFERENCES gk_work_orders(id);

-- PM-004: a lead-approved rule per checklist names which results raise a
-- correction, with its severity and deadline. A new rule appends a numbered
-- revision; the finding it raised names the rule it used. A correction's
-- assignee acknowledges it before it can be submitted.
CREATE TABLE gk_failure_rules (
  id TEXT PRIMARY KEY,
  checklist_id TEXT NOT NULL REFERENCES gk_checklists(id),
  number INTEGER NOT NULL,
  outcomes TEXT NOT NULL,
  severity TEXT NOT NULL CHECK (severity IN ('low', 'medium', 'high')),
  due_days INTEGER NOT NULL,
  active INTEGER NOT NULL,
  approved_by TEXT NOT NULL,
  approved_at INTEGER NOT NULL,
  UNIQUE (checklist_id, number)
);
CREATE TRIGGER gk_failure_rules_keep BEFORE UPDATE ON gk_failure_rules BEGIN SELECT RAISE(ABORT, 'gasket_immutable'); END;
ALTER TABLE gk_findings ADD COLUMN rule_id TEXT REFERENCES gk_failure_rules(id);
ALTER TABLE gk_work_orders ADD COLUMN acknowledged_at INTEGER;
ALTER TABLE gk_work_orders ADD COLUMN acknowledged_by TEXT;

-- ASSET-005: every reading keeps its unit, where it came from (a person on a
-- work order or a named feed) and its quality. taken_on is the source time,
-- entered_at the receipt time. Counter resets, replacements, rollovers and
-- corrected readings are explained, append-only adjustments: the reading they
-- correct is never rewritten.
ALTER TABLE gk_readings ADD COLUMN unit TEXT;
ALTER TABLE gk_readings ADD COLUMN provenance TEXT NOT NULL DEFAULT 'manual' CHECK (provenance IN ('manual', 'feed'));
ALTER TABLE gk_readings ADD COLUMN source TEXT;
ALTER TABLE gk_readings ADD COLUMN quality TEXT NOT NULL DEFAULT 'good' CHECK (quality IN ('good', 'suspect', 'stale'));

CREATE TABLE gk_meter_adjustments (
  id TEXT PRIMARY KEY,
  meter_id TEXT NOT NULL REFERENCES gk_meters(id),
  kind TEXT NOT NULL CHECK (kind IN ('reset', 'replacement', 'rollover', 'correction')),
  effective_on TEXT NOT NULL,
  last_value TEXT,
  start_value TEXT,
  reading_id TEXT REFERENCES gk_readings(id),
  value TEXT,
  reason TEXT NOT NULL,
  recorded_by TEXT NOT NULL,
  recorded_at INTEGER NOT NULL,
  CHECK ((kind = 'correction') = (reading_id IS NOT NULL AND value IS NOT NULL)),
  CHECK ((kind <> 'correction') = (last_value IS NOT NULL AND start_value IS NOT NULL))
);
CREATE INDEX gk_meter_adjustments_meter ON gk_meter_adjustments(meter_id, effective_on);
CREATE TRIGGER gk_meter_adjustments_keep BEFORE UPDATE ON gk_meter_adjustments BEGIN SELECT RAISE(ABORT, 'gasket_immutable'); END;
CREATE TRIGGER gk_meter_adjustments_stay BEFORE DELETE ON gk_meter_adjustments BEGIN SELECT RAISE(ABORT, 'gasket_immutable'); END;

-- ASSET-004 (slice): a declared asset state with its effective time and reason.
-- Reclassifying a change appends a new entry that names the one it corrects;
-- the original entry is never rewritten. Open downtime still reads as down.
CREATE TABLE gk_asset_states (
  id TEXT PRIMARY KEY,
  asset_id TEXT NOT NULL REFERENCES gk_assets(id),
  state TEXT NOT NULL CHECK (state IN ('in_service', 'degraded', 'down', 'out_of_service')),
  effective_on TEXT NOT NULL,
  reason TEXT NOT NULL,
  corrects TEXT REFERENCES gk_asset_states(id),
  recorded_by TEXT NOT NULL,
  recorded_at INTEGER NOT NULL
);
CREATE INDEX gk_asset_states_asset ON gk_asset_states(asset_id, effective_on);
CREATE TRIGGER gk_asset_states_keep BEFORE UPDATE ON gk_asset_states BEGIN SELECT RAISE(ABORT, 'gasket_immutable'); END;
CREATE TRIGGER gk_asset_states_stay BEFORE DELETE ON gk_asset_states BEGIN SELECT RAISE(ABORT, 'gasket_immutable'); END;

-- PM-003: a calendar schedule's policy (fixed or completion cadence, allowed
-- months and ISO weekdays, whether site closures move it, how far it may be
-- deferred), the nominal cadence date before the calendar moved it, the site's
-- closed days (holidays and shutdown windows, inclusive), and each skip or
-- deferral request with its independent decision, kept for good.
ALTER TABLE gk_schedules ADD COLUMN cadence TEXT NOT NULL DEFAULT 'fixed' CHECK (cadence IN ('fixed', 'completion'));
ALTER TABLE gk_schedules ADD COLUMN months TEXT;
ALTER TABLE gk_schedules ADD COLUMN weekdays TEXT;
ALTER TABLE gk_schedules ADD COLUMN observe_closures INTEGER NOT NULL DEFAULT 1;
ALTER TABLE gk_schedules ADD COLUMN max_defer_days INTEGER NOT NULL DEFAULT 14 CHECK (max_defer_days BETWEEN 0 AND 365);
ALTER TABLE gk_schedules ADD COLUMN nominal_date TEXT;
UPDATE gk_schedules SET nominal_date = next_due_date;

CREATE TABLE gk_closures (
  id TEXT PRIMARY KEY,
  kind TEXT NOT NULL CHECK (kind IN ('holiday', 'shutdown')),
  label TEXT NOT NULL,
  starts_on TEXT NOT NULL,
  ends_on TEXT NOT NULL,
  created_by TEXT NOT NULL,
  created_at INTEGER NOT NULL,
  CHECK (starts_on <= ends_on)
);

CREATE TABLE gk_schedule_exceptions (
  id TEXT PRIMARY KEY,
  schedule_id TEXT NOT NULL REFERENCES gk_schedules(id),
  kind TEXT NOT NULL CHECK (kind IN ('skip', 'defer')),
  occurrence TEXT NOT NULL,
  until TEXT,
  reason TEXT NOT NULL,
  requested_by TEXT NOT NULL,
  requested_at INTEGER NOT NULL,
  decision TEXT CHECK (decision IN ('approved', 'rejected')),
  decided_by TEXT,
  decided_at INTEGER,
  note TEXT,
  CHECK ((kind = 'defer') = (until IS NOT NULL))
);
CREATE UNIQUE INDEX gk_schedule_exceptions_pending ON gk_schedule_exceptions(schedule_id) WHERE decision IS NULL;
CREATE TRIGGER gk_schedule_exceptions_decided BEFORE UPDATE ON gk_schedule_exceptions WHEN OLD.decision IS NOT NULL BEGIN SELECT RAISE(ABORT, 'gasket_immutable'); END;
CREATE TRIGGER gk_schedule_exceptions_stay BEFORE DELETE ON gk_schedule_exceptions BEGIN SELECT RAISE(ABORT, 'gasket_immutable'); END;

-- PM-002: a schedule on a gauge or condition meter fires on its trigger
-- (above or below a threshold, or in chosen conditions, sustained for some
-- minutes) and re-arms past its reset value; trigger_fired_on is the source
-- time of the reading that last fired it. A schedule with a calendar and a
-- meter is due on whichever comes first, or only when both are due. Work a
-- trigger raised names the reading that raised it.
ALTER TABLE gk_schedules ADD COLUMN combine TEXT NOT NULL DEFAULT 'first' CHECK (combine IN ('first', 'both'));
ALTER TABLE gk_schedules ADD COLUMN trigger_when TEXT CHECK (trigger_when IS NULL OR trigger_when IN ('above', 'below', 'is'));
ALTER TABLE gk_schedules ADD COLUMN trigger_value TEXT;
ALTER TABLE gk_schedules ADD COLUMN reset_value TEXT;
ALTER TABLE gk_schedules ADD COLUMN sustain_minutes INTEGER NOT NULL DEFAULT 0 CHECK (sustain_minutes BETWEEN 0 AND 10080);
ALTER TABLE gk_schedules ADD COLUMN trigger_fired_on TEXT;
ALTER TABLE gk_work_orders ADD COLUMN trigger_reading_id TEXT REFERENCES gk_readings(id);

-- PM-001: the installation's own scheduler (a Cron Trigger every 15 minutes).
-- Each run is kept with its UTC time, what it issued and, when the scheduler had
-- not run for longer than 45 minutes, the gap: missed-run debt stays visible.
-- A work order the schedule issued names its occurrence (schedule and due date,
-- counter value or triggering reading), so the scheduler never issues one twice.
CREATE TABLE gk_scheduler_runs (
  id TEXT PRIMARY KEY,
  cron TEXT NOT NULL,
  ran_at INTEGER NOT NULL,
  created INTEGER NOT NULL,
  gap_minutes INTEGER,
  finished_at INTEGER NOT NULL
);
CREATE INDEX gk_scheduler_runs_at ON gk_scheduler_runs(ran_at);
ALTER TABLE gk_work_orders ADD COLUMN occurrence TEXT;
CREATE INDEX gk_work_orders_occurrence ON gk_work_orders(occurrence);

-- PLAN-002: teams, trades, shifts and accountable assignments. A team is a
-- named group of assignable people with one trade; a work order may name a
-- team, a trade and a shift. Collaborators record alongside the accountable
-- assignee; every reassignment keeps a handoff (people, shifts and a note).
-- Declined work gives each lead an in-app notice, so gk_notices takes a new kind.
CREATE TABLE gk_teams (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL UNIQUE COLLATE NOCASE,
  trade TEXT NOT NULL,
  created_by TEXT NOT NULL,
  created_at INTEGER NOT NULL
);

CREATE TABLE gk_team_members (
  team_id TEXT NOT NULL REFERENCES gk_teams(id),
  member_id TEXT NOT NULL REFERENCES gk_members(id),
  added_by TEXT NOT NULL,
  added_at INTEGER NOT NULL,
  PRIMARY KEY (team_id, member_id)
);

ALTER TABLE gk_work_orders ADD COLUMN team_id TEXT REFERENCES gk_teams(id);
ALTER TABLE gk_work_orders ADD COLUMN trade TEXT;
ALTER TABLE gk_work_orders ADD COLUMN shift TEXT;

CREATE TABLE gk_collaborators (
  work_order_id TEXT NOT NULL REFERENCES gk_work_orders(id),
  member_id TEXT NOT NULL REFERENCES gk_members(id),
  added_by TEXT NOT NULL,
  added_at INTEGER NOT NULL,
  removed_by TEXT,
  removed_at INTEGER,
  PRIMARY KEY (work_order_id, member_id)
);
CREATE INDEX gk_collaborators_member ON gk_collaborators(member_id) WHERE removed_at IS NULL;

CREATE TABLE gk_handoffs (
  id TEXT PRIMARY KEY,
  work_order_id TEXT NOT NULL REFERENCES gk_work_orders(id),
  from_id TEXT,
  to_id TEXT,
  from_shift TEXT,
  to_shift TEXT,
  note TEXT,
  by_id TEXT NOT NULL,
  at INTEGER NOT NULL
);
CREATE INDEX gk_handoffs_order ON gk_handoffs(work_order_id, at);

PRAGMA defer_foreign_keys = true;
CREATE TABLE gk_notices_next (
  id TEXT PRIMARY KEY,
  recipient_id TEXT NOT NULL,
  work_order_id TEXT NOT NULL REFERENCES gk_work_orders(id),
  kind TEXT NOT NULL CHECK (kind IN ('reminder', 'overdue', 'escalation_lead', 'escalation_supervisor', 'blocker_missed', 'declined')),
  occasion TEXT NOT NULL,
  text TEXT NOT NULL,
  created_at INTEGER NOT NULL,
  UNIQUE (recipient_id, occasion)
);
INSERT INTO gk_notices_next SELECT id, recipient_id, work_order_id, kind, occasion, text, created_at FROM gk_notices;
DROP TABLE gk_notices;
ALTER TABLE gk_notices_next RENAME TO gk_notices;
CREATE INDEX gk_notices_recipient ON gk_notices(recipient_id, created_at);

-- REPORT-004: estimated work, so backlog and completed work are counted in
-- hours as well as orders. A schedule may name a team and an estimate, which
-- the work it issues carries, so its due occurrences belong to that team even
-- before any work exists for them.
ALTER TABLE gk_work_orders ADD COLUMN estimate_minutes INTEGER CHECK (estimate_minutes IS NULL OR estimate_minutes BETWEEN 1 AND 60000);
ALTER TABLE gk_schedules ADD COLUMN team_id TEXT REFERENCES gk_teams(id);
ALTER TABLE gk_schedules ADD COLUMN estimate_minutes INTEGER CHECK (estimate_minutes IS NULL OR estimate_minutes BETWEEN 1 AND 60000);

-- PM-001: each site's lead time, the whole days ahead of its due date that
-- calendar PM work is issued (0 to 90, 7 by default).
ALTER TABLE gk_site ADD COLUMN lead_days INTEGER NOT NULL DEFAULT 7 CHECK (lead_days BETWEEN 0 AND 90);

-- REPORT-003: every stop (downtime on a work order) is either a planned stop or
-- a failure, optionally with a failure mode code, as recorded when the asset
-- went down. A lead corrects that classification by appending an entry with a
-- reason; the stop and every earlier classification stay as they were, and the
-- latest entry is the one the reliability report uses.
ALTER TABLE gk_downtime ADD COLUMN planned INTEGER NOT NULL DEFAULT 0 CHECK (planned IN (0, 1));
ALTER TABLE gk_downtime ADD COLUMN failure_mode TEXT REFERENCES gk_codes(id);

CREATE TABLE gk_downtime_classes (
  id TEXT PRIMARY KEY,
  downtime_id TEXT NOT NULL REFERENCES gk_downtime(id),
  planned INTEGER NOT NULL CHECK (planned IN (0, 1)),
  failure_mode TEXT REFERENCES gk_codes(id),
  reason TEXT NOT NULL,
  recorded_by TEXT NOT NULL,
  recorded_at INTEGER NOT NULL,
  CHECK (planned = 0 OR failure_mode IS NULL)
);
CREATE INDEX gk_downtime_classes_stop ON gk_downtime_classes(downtime_id, recorded_at);
CREATE TRIGGER gk_downtime_classes_keep BEFORE UPDATE ON gk_downtime_classes BEGIN SELECT RAISE(ABORT, 'gasket_immutable'); END;
CREATE TRIGGER gk_downtime_classes_stay BEFORE DELETE ON gk_downtime_classes BEGIN SELECT RAISE(ABORT, 'gasket_immutable'); END;

-- PART-002: reservations made in one write, and a kit's lines, keep the order
-- they were given in an explicit column, so they list the same way after an
-- archive is restored (row ids are not carried over).
ALTER TABLE gk_reservations ADD COLUMN line INTEGER NOT NULL DEFAULT 0;
ALTER TABLE gk_kit_lines ADD COLUMN position INTEGER NOT NULL DEFAULT 0;

-- ASSET-001: the asset and location hierarchy. Every register entry has a
-- level (building, line, machine or component) and an optional parent; an
-- entry without a parent sits directly under the site. Moves are audited
-- (asset.move) with the parents they left and joined.
ALTER TABLE gk_assets ADD COLUMN parent_id TEXT REFERENCES gk_assets(id);
ALTER TABLE gk_assets ADD COLUMN level TEXT NOT NULL DEFAULT 'machine' CHECK (level IN ('building', 'line', 'machine', 'component'));
CREATE INDEX gk_assets_parent ON gk_assets(parent_id);

-- REPORT-005: repair cost entries a lead records on a work order (USD cents; a
-- correction is a further entry, never an edit), and documented lost-production
-- rates per register entry (USD cents per production hour; a NULL rate records
-- that the loss is unknown). The latest rate of an entry counts.
CREATE TABLE gk_work_costs (
  id TEXT PRIMARY KEY,
  work_order_id TEXT NOT NULL REFERENCES gk_work_orders(id),
  category TEXT NOT NULL CHECK (category IN ('parts', 'labor', 'contractor', 'other')),
  cents INTEGER NOT NULL,
  note TEXT NOT NULL,
  recorded_by TEXT NOT NULL,
  recorded_at INTEGER NOT NULL
);
CREATE INDEX gk_work_costs_work ON gk_work_costs(work_order_id, recorded_at);
CREATE TRIGGER gk_work_costs_keep BEFORE UPDATE ON gk_work_costs BEGIN SELECT RAISE(ABORT, 'gasket_immutable'); END;
CREATE TRIGGER gk_work_costs_stay BEFORE DELETE ON gk_work_costs BEGIN SELECT RAISE(ABORT, 'gasket_immutable'); END;

CREATE TABLE gk_loss_rates (
  id TEXT PRIMARY KEY,
  asset_id TEXT NOT NULL REFERENCES gk_assets(id),
  cents_per_hour INTEGER CHECK (cents_per_hour IS NULL OR cents_per_hour >= 0),
  basis TEXT NOT NULL,
  recorded_by TEXT NOT NULL,
  recorded_at INTEGER NOT NULL
);
CREATE INDEX gk_loss_rates_asset ON gk_loss_rates(asset_id, recorded_at);
CREATE TRIGGER gk_loss_rates_keep BEFORE UPDATE ON gk_loss_rates BEGIN SELECT RAISE(ABORT, 'gasket_immutable'); END;
CREATE TRIGGER gk_loss_rates_stay BEFORE DELETE ON gk_loss_rates BEGIN SELECT RAISE(ABORT, 'gasket_immutable'); END;

-- PLAN-001 (slice): custom work fields, required on every work order or by a
-- template, and waiting statuses whose definition names who may use them.
CREATE TABLE gk_work_fields (
  id TEXT PRIMARY KEY,
  label TEXT NOT NULL UNIQUE COLLATE NOCASE,
  kind TEXT NOT NULL CHECK (kind IN ('text', 'number', 'choice')),
  options TEXT,
  required INTEGER NOT NULL DEFAULT 0 CHECK (required IN (0, 1)),
  position INTEGER NOT NULL,
  retired_at INTEGER,
  created_by TEXT NOT NULL,
  created_at INTEGER NOT NULL
);
CREATE TABLE gk_work_field_values (
  work_order_id TEXT NOT NULL REFERENCES gk_work_orders(id),
  field_id TEXT NOT NULL REFERENCES gk_work_fields(id),
  value TEXT NOT NULL,
  set_by TEXT NOT NULL,
  set_at INTEGER NOT NULL,
  PRIMARY KEY (work_order_id, field_id)
);
-- A template requires fields (a JSON list of field ids) and evidence; work made
-- from it keeps the requirements of that revision.
ALTER TABLE gk_work_templates ADD COLUMN required_fields TEXT;
ALTER TABLE gk_work_templates ADD COLUMN requires_evidence INTEGER NOT NULL DEFAULT 0 CHECK (requires_evidence IN (0, 1));
ALTER TABLE gk_work_orders ADD COLUMN required_fields TEXT;
ALTER TABLE gk_work_orders ADD COLUMN requires_evidence INTEGER NOT NULL DEFAULT 0 CHECK (requires_evidence IN (0, 1));

CREATE TABLE gk_work_statuses (
  id TEXT PRIMARY KEY,
  label TEXT NOT NULL UNIQUE COLLATE NOCASE,
  roles TEXT NOT NULL,
  retired_at INTEGER,
  created_by TEXT NOT NULL,
  created_at INTEGER NOT NULL
);
ALTER TABLE gk_work_orders ADD COLUMN waiting_status TEXT REFERENCES gk_work_statuses(id);

-- FIELD-009: technician-created and after-the-fact work. A work order records
-- the door it was created through (web form or JSON API), and work recorded
-- after it was done carries its past start and end (site-local minutes). A
-- template may name a checklist whose current revision its work pins. The
-- owner turns the technician create-work right off or on for the site.
ALTER TABLE gk_work_orders ADD COLUMN created_via TEXT;
ALTER TABLE gk_work_orders ADD COLUMN work_started_on TEXT;
ALTER TABLE gk_work_orders ADD COLUMN work_ended_on TEXT;
ALTER TABLE gk_work_templates ADD COLUMN checklist_id TEXT REFERENCES gk_checklists(id);
ALTER TABLE gk_site ADD COLUMN technician_create_work INTEGER NOT NULL DEFAULT 1 CHECK (technician_create_work IN (0, 1));

-- FIELD-004: typed checklist steps keep the value entered (a number, text or
-- option); evidence may answer one step (a required photo); and a supervisor's
-- exception on a step, with its reason, is kept unchanged.
ALTER TABLE gk_results ADD COLUMN value TEXT;
ALTER TABLE gk_result_log ADD COLUMN value TEXT;
ALTER TABLE gk_evidence ADD COLUMN item INTEGER;
CREATE TABLE gk_step_exceptions (
  id TEXT PRIMARY KEY,
  work_order_id TEXT NOT NULL REFERENCES gk_work_orders(id),
  item INTEGER NOT NULL,
  reason TEXT NOT NULL,
  granted_by TEXT NOT NULL,
  granted_at INTEGER NOT NULL,
  UNIQUE (work_order_id, item)
);
CREATE TRIGGER gk_step_exceptions_keep BEFORE UPDATE ON gk_step_exceptions BEGIN SELECT RAISE(ABORT, 'gasket_immutable'); END;

-- ASSET-008: multi-asset inspection routes. A route is an ordered list of
-- stops, each an asset and the checklist done there. Issuing a route makes a
-- run with one work order per stop, pinned to that checklist's current
-- revision. A missed stop keeps its reason and stays open; a run is signed off
-- only once every stop is closed.
CREATE TABLE gk_routes (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL UNIQUE COLLATE NOCASE,
  created_by TEXT NOT NULL,
  created_at INTEGER NOT NULL
);
CREATE TABLE gk_route_stops (
  route_id TEXT NOT NULL REFERENCES gk_routes(id),
  position INTEGER NOT NULL,
  asset_id TEXT NOT NULL REFERENCES gk_assets(id),
  checklist_id TEXT NOT NULL REFERENCES gk_checklists(id),
  PRIMARY KEY (route_id, position)
);
CREATE TABLE gk_route_runs (
  id TEXT PRIMARY KEY,
  route_id TEXT NOT NULL REFERENCES gk_routes(id),
  due_date TEXT NOT NULL,
  issued_by TEXT NOT NULL,
  issued_at INTEGER NOT NULL,
  signed_by TEXT,
  signed_at INTEGER
);
ALTER TABLE gk_work_orders ADD COLUMN route_run_id TEXT REFERENCES gk_route_runs(id);
ALTER TABLE gk_work_orders ADD COLUMN route_position INTEGER;
ALTER TABLE gk_work_orders ADD COLUMN missed_reason TEXT;
ALTER TABLE gk_work_orders ADD COLUMN missed_by TEXT;
ALTER TABLE gk_work_orders ADD COLUMN missed_at INTEGER;

-- ASSET-008: scheduled routes, required tools and calibration tasks.
-- A route may repeat every N days from its first due date; the scheduler issues
-- one run per occurrence. Routes and schedules may name the tools their work
-- needs; each issued work order lists them and the person doing it records
-- which one was used. A calibration task is a schedule on an instrument whose
-- procedure carries the tolerances (number steps with inclusive limits) and a
-- grace window in days after its due date; approving its work keeps the
-- attached certificate as the instrument's next certificate version.
ALTER TABLE gk_routes ADD COLUMN every_days INTEGER CHECK (every_days IS NULL OR every_days BETWEEN 1 AND 3660);
ALTER TABLE gk_routes ADD COLUMN next_due_date TEXT;
ALTER TABLE gk_routes ADD COLUMN assignee_id TEXT REFERENCES gk_members(id);
ALTER TABLE gk_routes ADD COLUMN tools TEXT;
ALTER TABLE gk_route_runs ADD COLUMN occurrence TEXT;
CREATE UNIQUE INDEX gk_route_runs_occurrence ON gk_route_runs(occurrence) WHERE occurrence IS NOT NULL;
ALTER TABLE gk_schedules ADD COLUMN tools TEXT;
ALTER TABLE gk_schedules ADD COLUMN calibration INTEGER NOT NULL DEFAULT 0;
ALTER TABLE gk_schedules ADD COLUMN grace_days INTEGER CHECK (grace_days IS NULL OR grace_days BETWEEN 0 AND 90);
CREATE TABLE gk_work_tools (
  work_order_id TEXT NOT NULL REFERENCES gk_work_orders(id),
  position INTEGER NOT NULL,
  name TEXT NOT NULL,
  identifier TEXT,
  recorded_by TEXT,
  recorded_at INTEGER,
  PRIMARY KEY (work_order_id, position)
);
ALTER TABLE gk_evidence ADD COLUMN certificate INTEGER NOT NULL DEFAULT 0;
CREATE TABLE gk_calibration_certificates (
  id TEXT PRIMARY KEY,
  schedule_id TEXT NOT NULL REFERENCES gk_schedules(id),
  version INTEGER NOT NULL,
  work_order_id TEXT NOT NULL UNIQUE REFERENCES gk_work_orders(id),
  evidence_id TEXT NOT NULL REFERENCES gk_evidence(id),
  checklist_revision_id TEXT NOT NULL REFERENCES gk_checklist_revisions(id),
  result TEXT NOT NULL CHECK (result IN ('in_tolerance', 'out_of_tolerance')),
  due_date TEXT NOT NULL,
  calibrated_on TEXT NOT NULL,
  on_time INTEGER NOT NULL,
  approved_by TEXT NOT NULL,
  approved_at INTEGER NOT NULL,
  UNIQUE (schedule_id, version)
);
CREATE TRIGGER gk_calibration_certificates_keep BEFORE UPDATE ON gk_calibration_certificates BEGIN SELECT RAISE(ABORT, 'gasket_immutable'); END;

-- PART-007: inventory valuation at moving-average cost, in whole US cents.
-- Every movement written from now on carries its signed value beside its
-- signed quantity, so stock value is the sum of movement values exactly as
-- on-hand is the sum of quantities. A receipt keeps its unit price, freight
-- and sales tax; a part keeps its current vendor price, which values nothing
-- by itself. Movements from before valuation (and moved-in opening stock)
-- have no value and are reported as unpriced, never as a cost.
ALTER TABLE gk_part_moves ADD COLUMN value_cents INTEGER;
ALTER TABLE gk_part_moves ADD COLUMN unit_price_cents INTEGER CHECK (unit_price_cents IS NULL OR unit_price_cents >= 0);
ALTER TABLE gk_part_moves ADD COLUMN freight_cents INTEGER CHECK (freight_cents IS NULL OR freight_cents >= 0);
ALTER TABLE gk_part_moves ADD COLUMN tax_cents INTEGER CHECK (tax_cents IS NULL OR tax_cents >= 0);
ALTER TABLE gk_parts ADD COLUMN price_cents INTEGER CHECK (price_cents IS NULL OR price_cents >= 0);

-- PM-008: installation-owned automation controls and durable job evidence.
CREATE TABLE gk_automation_rules (
  id TEXT PRIMARY KEY CHECK (id IN ('pm','routes','chase','expiry')),
  revision INTEGER NOT NULL DEFAULT 1,
  paused INTEGER NOT NULL DEFAULT 0 CHECK (paused IN (0,1)),
  reason TEXT NOT NULL DEFAULT '',
  changed_by TEXT,
  changed_at INTEGER NOT NULL
);
INSERT INTO gk_automation_rules (id,changed_at) VALUES ('pm',0),('routes',0),('chase',0),('expiry',0);
CREATE TABLE gk_automation_jobs (
  id TEXT PRIMARY KEY,
  rule_id TEXT NOT NULL REFERENCES gk_automation_rules(id),
  rule_revision INTEGER NOT NULL,
  source TEXT NOT NULL CHECK (source IN ('cron','catchup','reading')),
  started_at INTEGER NOT NULL,
  finished_at INTEGER,
  state TEXT NOT NULL CHECK (state IN ('running','completed','failed','paused')),
  input TEXT NOT NULL,
  output TEXT,
  error TEXT
);
CREATE INDEX gk_automation_jobs_rule ON gk_automation_jobs(rule_id,started_at);
ALTER TABLE gk_scheduler_runs ADD COLUMN state TEXT NOT NULL DEFAULT 'completed';
ALTER TABLE gk_scheduler_runs ADD COLUMN error TEXT;
ALTER TABLE gk_notices ADD COLUMN automation_job_id TEXT REFERENCES gk_automation_jobs(id);
ALTER TABLE gk_notices ADD COLUMN automation_revision INTEGER;
CREATE TRIGGER gk_automation_authority_guard BEFORE INSERT ON gk_guard
WHEN NEW.code = 'automation_changed' AND NEW.ok = 0
BEGIN SELECT RAISE(ABORT, 'gasket_guard_automation_changed'); END;

-- PM-009: immutable explicit task equivalences and occurrence satisfaction.
CREATE TABLE gk_nested_maps (
 id TEXT PRIMARY KEY, higher TEXT NOT NULL REFERENCES gk_schedules(id), lower TEXT NOT NULL REFERENCES gk_schedules(id),
 revision INTEGER NOT NULL, higher_revision TEXT NOT NULL REFERENCES gk_checklist_revisions(id), lower_revision TEXT NOT NULL REFERENCES gk_checklist_revisions(id),
 tasks TEXT NOT NULL, reason TEXT NOT NULL, created_by TEXT NOT NULL, created_at INTEGER NOT NULL,
 UNIQUE(higher,lower,revision), CHECK(higher<>lower)
);
CREATE TRIGGER gk_nested_maps_keep BEFORE UPDATE ON gk_nested_maps BEGIN SELECT RAISE(ABORT,'gasket_immutable'); END;
CREATE TRIGGER gk_nested_maps_stay BEFORE DELETE ON gk_nested_maps BEGIN SELECT RAISE(ABORT,'gasket_immutable'); END;
CREATE TABLE gk_nested_satisfaction (
 id TEXT PRIMARY KEY, mapping TEXT NOT NULL REFERENCES gk_nested_maps(id), higher_work TEXT NOT NULL REFERENCES gk_work_orders(id),
 lower_work TEXT NOT NULL UNIQUE REFERENCES gk_work_orders(id), higher_version INTEGER NOT NULL, lower_version INTEGER NOT NULL,
 occurrence TEXT NOT NULL, evidence TEXT NOT NULL, created_by TEXT NOT NULL, created_at INTEGER NOT NULL
